-- Sprint 10 additive migration. Review and apply manually.
create table public.leads(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),name text not null,phone text not null,email text,whatsapp text,preferred_language text,source text not null,status text not null check(status in('new','contacted','qualified','meeting_scheduled','viewing_scheduled','negotiation','won','lost','archived')),priority text not null check(priority in('low','medium','high','urgent','vip')),budget numeric(18,2),currency char(3)not null,buying_purpose text,property_type text,preferred_locations text[]not null default'{}',bedrooms integer,timeline text,financing text,assigned_agent_id uuid references auth.users(id),lead_score integer check(lead_score between 0 and 100),temperature text check(temperature is null or temperature in('hot','warm','cold')),ai_qualified boolean not null default false,expected_closing date,last_activity_at timestamptz,do_not_contact boolean not null default false,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.lead_property_interests(lead_id uuid not null references public.leads(id),property_id uuid not null references public.properties(id),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),created_at timestamptz not null default now(),primary key(lead_id,property_id));
create table public.lead_tags(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),tag text not null,created_at timestamptz not null default now(),unique(lead_id,tag));
create table public.lead_saved_views(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),user_id uuid not null references auth.users(id),name text not null,query jsonb not null default'{}',is_default boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,user_id,name));
create index leads_workspace_active_updated_idx on public.leads(organization_id,workspace_id,updated_at desc)where deleted_at is null;create index leads_workspace_status_idx on public.leads(organization_id,workspace_id,status,priority)where deleted_at is null;create index leads_assignment_idx on public.leads(workspace_id,assigned_agent_id)where deleted_at is null;create index leads_search_idx on public.leads using gin(to_tsvector('simple',coalesce(name,'')||' '||coalesce(email,'')||' '||coalesce(phone,'')))where deleted_at is null;
alter table public.leads enable row level security;alter table public.lead_property_interests enable row level security;alter table public.lead_tags enable row level security;alter table public.lead_saved_views enable row level security;
create policy "leads_workspace_read" on public.leads for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=leads.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "lead_interests_workspace_read" on public.lead_property_interests for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=lead_property_interests.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "lead_tags_workspace_read" on public.lead_tags for select to authenticated using(public.is_organization_member(organization_id)and exists(select 1 from workspace_members wm where wm.workspace_id=lead_tags.workspace_id and wm.user_id=auth.uid()and wm.status='active'));
create policy "lead_views_owner" on public.lead_saved_views for all to authenticated using(user_id=auth.uid()and public.is_organization_member(organization_id))with check(user_id=auth.uid()and public.is_organization_member(organization_id));
create or replace function public.create_lead(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_user uuid:=auth.uid();v_org uuid;v_id uuid;v_role text;v_value text;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=v_user and status='active';v_role:=current_workspace_role(p_workspace_id);if v_org is null or v_role not in('organization_owner','organization_admin','sales_manager')then raise exception'insufficient lead permission';end if;insert into leads(organization_id,workspace_id,name,phone,email,whatsapp,preferred_language,source,status,priority,budget,currency,buying_purpose,property_type,preferred_locations,bedrooms,timeline,financing,assigned_agent_id,expected_closing,created_by,updated_by)values(v_org,p_workspace_id,p_input->>'name',p_input->>'phone',nullif(p_input->>'email',''),nullif(p_input->>'whatsapp',''),p_input->>'preferredLanguage',p_input->>'source',p_input->>'status',p_input->>'priority',nullif(p_input->>'budget','')::numeric,upper(p_input->>'currency'),p_input->>'buyingPurpose',p_input->>'propertyType',array(select jsonb_array_elements_text(coalesce(p_input->'preferredLocations','[]'))),nullif(p_input->>'bedrooms','')::integer,p_input->>'timeline',p_input->>'financing',nullif(p_input->>'assignedAgentId','')::uuid,nullif(p_input->>'expectedClosing','')::date,v_user,v_user)returning id into v_id;for v_value in select jsonb_array_elements_text(coalesce(p_input->'tags','[]'))loop insert into lead_tags(lead_id,organization_id,workspace_id,tag)values(v_id,v_org,p_workspace_id,v_value)on conflict do nothing;end loop;for v_value in select jsonb_array_elements_text(coalesce(p_input->'propertyInterestIds','[]'))loop insert into lead_property_interests(lead_id,property_id,organization_id,workspace_id)select v_id,p.id,v_org,p_workspace_id from properties p where p.id=v_value::uuid and p.organization_id=v_org and p.workspace_id=p_workspace_id and p.deleted_at is null on conflict do nothing;end loop;return v_id;end$$;
create or replace function public.update_lead(p_lead_id uuid,p_expected_version integer,p_input jsonb)returns void language plpgsql security definer set search_path=public as $$declare v_user uuid:=auth.uid();v_lead leads%rowtype;v_role text;v_value text;begin select*into v_lead from leads where id=p_lead_id and deleted_at is null for update;if not found or not is_organization_member(v_lead.organization_id)then raise exception'lead not found';end if;v_role:=current_workspace_role(v_lead.workspace_id);if v_role not in('organization_owner','organization_admin','sales_manager')and not(v_role='agent'and v_lead.assigned_agent_id=v_user)then raise exception'insufficient lead permission';end if;if v_lead.version<>p_expected_version then raise exception'lead changed by another user';end if;update leads set name=p_input->>'name',phone=p_input->>'phone',email=nullif(p_input->>'email',''),whatsapp=nullif(p_input->>'whatsapp',''),preferred_language=p_input->>'preferredLanguage',source=p_input->>'source',status=p_input->>'status',priority=p_input->>'priority',budget=nullif(p_input->>'budget','')::numeric,currency=upper(p_input->>'currency'),buying_purpose=p_input->>'buyingPurpose',property_type=p_input->>'propertyType',preferred_locations=array(select jsonb_array_elements_text(coalesce(p_input->'preferredLocations','[]'))),bedrooms=nullif(p_input->>'bedrooms','')::integer,timeline=p_input->>'timeline',financing=p_input->>'financing',assigned_agent_id=case when v_role in('organization_owner','organization_admin','sales_manager')then nullif(p_input->>'assignedAgentId','')::uuid else assigned_agent_id end,expected_closing=nullif(p_input->>'expectedClosing','')::date,updated_by=v_user,updated_at=now(),version=version+1 where id=p_lead_id;delete from lead_tags where lead_id=p_lead_id;for v_value in select jsonb_array_elements_text(coalesce(p_input->'tags','[]'))loop insert into lead_tags(lead_id,organization_id,workspace_id,tag)values(p_lead_id,v_lead.organization_id,v_lead.workspace_id,v_value)on conflict do nothing;end loop;delete from lead_property_interests where lead_id=p_lead_id;for v_value in select jsonb_array_elements_text(coalesce(p_input->'propertyInterestIds','[]'))loop insert into lead_property_interests(lead_id,property_id,organization_id,workspace_id)select p_lead_id,p.id,v_lead.organization_id,v_lead.workspace_id from properties p where p.id=v_value::uuid and p.organization_id=v_lead.organization_id and p.workspace_id=v_lead.workspace_id and p.deleted_at is null on conflict do nothing;end loop;end$$;
create or replace function public.assign_leads(p_workspace_id uuid,p_lead_ids uuid[],p_agent_id uuid)returns integer language plpgsql security definer set search_path=public as $$declare v_role text:=current_workspace_role(p_workspace_id);v_count integer;begin if v_role not in('organization_owner','organization_admin','sales_manager')then raise exception'insufficient assignment permission';end if;if not exists(select 1 from workspace_members where workspace_id=p_workspace_id and user_id=p_agent_id and status='active')then raise exception'assignee is not an active workspace member';end if;update leads set assigned_agent_id=p_agent_id,updated_by=auth.uid(),updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=any(p_lead_ids)and deleted_at is null;get diagnostics v_count=row_count;return v_count;end$$;
create or replace function public.change_lead_status(p_workspace_id uuid,p_lead_ids uuid[],p_status text)returns integer language plpgsql security definer set search_path=public as $$declare v_role text:=current_workspace_role(p_workspace_id);v_count integer;begin if p_status not in('new','contacted','qualified','meeting_scheduled','viewing_scheduled','negotiation','won','lost','archived')then raise exception'invalid status';end if;update leads set status=p_status,updated_by=auth.uid(),updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=any(p_lead_ids)and deleted_at is null and(v_role in('organization_owner','organization_admin','sales_manager')or(v_role='agent'and assigned_agent_id=auth.uid()));get diagnostics v_count=row_count;return v_count;end$$;
create or replace function public.archive_leads(p_workspace_id uuid,p_lead_ids uuid[])returns integer language plpgsql security definer set search_path=public as $$declare v_role text:=current_workspace_role(p_workspace_id);v_count integer;begin if v_role not in('organization_owner','organization_admin','sales_manager')then raise exception'insufficient archive permission';end if;update leads set status='archived',deleted_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where workspace_id=p_workspace_id and id=any(p_lead_ids)and deleted_at is null;get diagnostics v_count=row_count;return v_count;end$$;
revoke all on function public.create_lead(uuid,jsonb),public.update_lead(uuid,integer,jsonb),public.assign_leads(uuid,uuid[],uuid),public.change_lead_status(uuid,uuid[],text),public.archive_leads(uuid,uuid[])from public;grant execute on function public.create_lead(uuid,jsonb),public.update_lead(uuid,integer,jsonb),public.assign_leads(uuid,uuid[],uuid),public.change_lead_status(uuid,uuid[],text),public.archive_leads(uuid,uuid[])to authenticated;

